"""Calibration: inclusive interval coverage, exact scores and bank entries.

Validation coverage, the score fraction and the exact-match key census use only
integer or Fraction arithmetic, so the contract's strict inequalities and the
clipped exact census are honoured without tolerance.
"""
from fractions import Fraction
from itertools import product

PADDING = 1514
MAX_VALUE = 3028
ENUMERATION_SOFT_LIMIT = 4_000_000


def real_prefix(values):
    for index, value in enumerate(values):
        if value == PADDING:
            return values[:index]
    return values[:]


class RowIndex:
    """Distinct validation real prefixes per class with their multiplicities."""

    def __init__(self, rows, classes):
        self.classes = classes
        self.counts = [0] * classes
        self.by_class = [[] for _ in range(classes)]
        self.lookup = [{} for _ in range(classes)]
        self.positions = {}
        for row in rows:
            cls = row['class']
            self.counts[cls] += 1
            prefix = tuple(real_prefix(row['values']))
